head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.fn_openPopup = function(a) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "popup1_" + a,
        type: "wframePopup",
        width: 400 + "px",
        height: 400 + "px",
        top: 100 + "px",
        left: 100 + "px",
        modal: true,
        useModalStack: true,
        className: "",
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true
    };
    $p.openPopup("wframePopup_exceldown_popop_WESD-787_(WSQ-4809)_popup1.xml", options);
};
scwin.trigger3_onclick = function(e) {
    scwin.fn_openPopup("aaa");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
